"use client"

import * as React from "react"
import { ListFilterIcon } from "lucide-react"

import { cn } from "@/registry/default/lib/utils"
import {
  createFilter,
  type Filter,
  type FilterField,
} from "@/registry/default/lib/filter"
import { useControllableState } from "@/registry/default/hooks/use-controllable-state"
import { Button } from "@/registry/default/ui/button"
import { FilterChip } from "@/registry/default/ui/filter-chip"
import { FilterMenu, FilterMenuItem } from "@/registry/default/ui/filter-menu"

function FilterBuilder({
  fields,
  value,
  defaultValue = [],
  onValueChange,
  "aria-label": ariaLabel = "Filters",
  className,
  ...props
}: Omit<React.ComponentProps<"div">, "defaultValue" | "onChange"> & {
  fields: FilterField[]
  value?: Filter[]
  defaultValue?: Filter[]
  onValueChange?: (filters: Filter[]) => void
}) {
  const { value: filters, setValue: setFilters } = useControllableState({
    value,
    defaultValue,
    onChange: onValueChange,
  })
  const [newFilterId, setNewFilterId] = React.useState<string | null>(null)
  const didAddFilterRef = React.useRef(false)
  const fieldsById = new Map(fields.map((field) => [field.id, field]))

  function addFilter(field: FilterField) {
    const filter = createFilter(field)
    setFilters((current) => [...current, filter])
    setNewFilterId(filter.id)
    didAddFilterRef.current = true
  }

  function updateFilter(next: Filter) {
    setFilters((current) =>
      current.map((filter) => (filter.id === next.id ? next : filter))
    )
  }

  function removeFilter(id: string) {
    setFilters((current) => current.filter((filter) => filter.id !== id))
  }

  return (
    <div
      role="group"
      aria-label={ariaLabel}
      data-slot="filter-builder"
      className={cn("flex flex-wrap items-center gap-2", className)}
      {...props}
    >
      {filters.map((filter) => {
        const field = fieldsById.get(filter.fieldId)
        if (!field) return null
        return (
          <FilterChip
            key={filter.id}
            field={field}
            filter={filter}
            isNew={filter.id === newFilterId}
            onFilterChange={updateFilter}
            onRemove={() => removeFilter(filter.id)}
          />
        )
      })}
      <FilterMenu
        onCloseAutoFocus={(event) => {
          if (!didAddFilterRef.current) return
          didAddFilterRef.current = false
          event.preventDefault()
        }}
        trigger={
          <Button
            variant="outline"
            size="sm"
            data-slot="filter-builder-add"
            aria-label="Add filter"
            className="border-dashed"
          >
            <ListFilterIcon />
            {filters.length === 0 && "Filter"}
          </Button>
        }
      >
        {fields.map((field) => (
          <FilterMenuItem key={field.id} onSelect={() => addFilter(field)}>
            {field.icon}
            {field.label}
          </FilterMenuItem>
        ))}
      </FilterMenu>
      {filters.length > 0 && (
        <Button
          variant="ghost"
          size="sm"
          data-slot="filter-builder-clear"
          onClick={() => setFilters([])}
        >
          Clear
        </Button>
      )}
    </div>
  )
}

export { FilterBuilder }

"use client"

import * as React from "react"
import { XIcon } from "lucide-react"

import { cn } from "@/registry/default/lib/utils"
import {
  operatorLabel,
  operatorsFor,
  type Filter,
  type FilterField,
} from "@/registry/default/lib/filter"
import { FilterMenu, FilterMenuItem } from "@/registry/default/ui/filter-menu"
import { Input } from "@/registry/default/ui/input"
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from "@/registry/default/ui/popover"

const segmentClassName =
  "flex items-center gap-1.5 px-2 outline-none hover:bg-accent focus-visible:bg-accent focus-visible:ring-[3px] focus-visible:ring-ring/50 focus-visible:ring-inset data-popup-open:bg-accent data-[state=open]:bg-accent [&_svg]:size-3.5"

function ValueLabel({ text }: { text: string }) {
  if (!text) return <span className="text-muted-foreground">Any</span>
  return <span className="max-w-40 truncate font-medium">{text}</span>
}

function SelectValueEditor({
  field,
  filter,
  defaultOpen,
  onCommit,
  onDismissEmpty,
}: FilterValueEditorProps) {
  const hasPickedRef = React.useRef(false)
  const selected = field.options?.find(
    (option) => option.value === filter.value
  )

  return (
    <FilterMenu
      defaultOpen={defaultOpen}
      onOpenChange={(open) => {
        if (open || filter.value || hasPickedRef.current) return
        onDismissEmpty()
      }}
      trigger={
        <button
          type="button"
          aria-label={`${field.label} value`}
          className={segmentClassName}
        >
          <ValueLabel text={selected?.label ?? ""} />
        </button>
      }
    >
      {field.options?.map((option) => (
        <FilterMenuItem
          key={option.value}
          isSelected={option.value === filter.value}
          onSelect={() => {
            hasPickedRef.current = true
            onCommit(option.value)
          }}
        >
          {option.label}
        </FilterMenuItem>
      ))}
    </FilterMenu>
  )
}

function TypedValueEditor({
  field,
  filter,
  defaultOpen,
  onCommit,
  onDismissEmpty,
}: FilterValueEditorProps) {
  const [isOpen, setIsOpen] = React.useState(defaultOpen)
  const [draft, setDraft] = React.useState(filter.value)

  function handleOpenChange(open: boolean) {
    setIsOpen(open)
    if (open) return setDraft(filter.value)
    if (draft.trim()) return onCommit(draft.trim())
    onDismissEmpty()
  }

  return (
    <Popover open={isOpen} onOpenChange={handleOpenChange}>
      <PopoverTrigger
        aria-label={`${field.label} value`}
        className={segmentClassName}
      >
        <ValueLabel text={filter.value} />
      </PopoverTrigger>
      <PopoverContent align="start" className="w-56 p-2">
        <Input
          autoFocus
          aria-label={`${field.label} value`}
          type={field.type === "number" ? "number" : "text"}
          value={draft}
          placeholder={`Filter by ${field.label.toLowerCase()}`}
          onChange={(event) => setDraft(event.target.value)}
          onKeyDown={(event) => {
            if (event.key === "Enter") handleOpenChange(false)
          }}
          className="h-8"
        />
      </PopoverContent>
    </Popover>
  )
}

type FilterValueEditorProps = {
  field: FilterField
  filter: Filter
  defaultOpen: boolean
  onCommit: (value: string) => void
  onDismissEmpty: () => void
}

function FilterChip({
  field,
  filter,
  isNew = false,
  onFilterChange,
  onRemove,
  className,
  ...props
}: Omit<React.ComponentProps<"div">, "onChange"> & {
  field: FilterField
  filter: Filter
  isNew?: boolean
  onFilterChange: (filter: Filter) => void
  onRemove: () => void
}) {
  const ValueEditor =
    field.type === "select" ? SelectValueEditor : TypedValueEditor

  return (
    <div
      data-slot="filter-chip"
      className={cn(
        "inline-flex h-8 items-stretch divide-x overflow-hidden rounded-md border bg-background text-sm shadow-xs dark:bg-input/30",
        className
      )}
      {...props}
    >
      <span className="flex items-center gap-1.5 px-2 text-muted-foreground [&_svg]:size-3.5">
        {field.icon}
        {field.label}
      </span>
      <FilterMenu
        trigger={
          <button
            type="button"
            aria-label={`${field.label} operator`}
            className={cn(segmentClassName, "text-muted-foreground")}
          >
            {operatorLabel(filter.operator)}
          </button>
        }
      >
        {operatorsFor(field.type).map((operator) => (
          <FilterMenuItem
            key={operator}
            isSelected={operator === filter.operator}
            onSelect={() => onFilterChange({ ...filter, operator })}
          >
            {operatorLabel(operator)}
          </FilterMenuItem>
        ))}
      </FilterMenu>
      <ValueEditor
        field={field}
        filter={filter}
        defaultOpen={isNew}
        onCommit={(value) => onFilterChange({ ...filter, value })}
        onDismissEmpty={onRemove}
      />
      <button
        type="button"
        aria-label={`Remove ${field.label} filter`}
        onClick={onRemove}
        className={segmentClassName}
      >
        <XIcon />
      </button>
    </div>
  )
}

export { FilterChip }

"use client"

import * as React from "react"
import { CheckIcon } from "lucide-react"
import { DropdownMenu as DropdownMenuPrimitive } from "radix-ui"

import { cn } from "@/registry/default/lib/utils"

function FilterMenu({
  trigger,
  defaultOpen,
  onOpenChange,
  onCloseAutoFocus,
  align = "start",
  children,
}: {
  trigger: React.ReactNode
  defaultOpen?: boolean
  onOpenChange?: (open: boolean) => void
  onCloseAutoFocus?: React.ComponentProps<
    typeof DropdownMenuPrimitive.Content
  >["onCloseAutoFocus"]
  align?: React.ComponentProps<typeof DropdownMenuPrimitive.Content>["align"]
  children: React.ReactNode
}) {
  return (
    <DropdownMenuPrimitive.Root
      modal={false}
      defaultOpen={defaultOpen}
      onOpenChange={onOpenChange}
    >
      <DropdownMenuPrimitive.Trigger asChild>
        {trigger}
      </DropdownMenuPrimitive.Trigger>
      <DropdownMenuPrimitive.Portal>
        <DropdownMenuPrimitive.Content
          data-slot="filter-menu"
          align={align}
          sideOffset={4}
          onCloseAutoFocus={onCloseAutoFocus}
          className="z-50 max-h-(--radix-dropdown-menu-content-available-height) min-w-36 origin-(--radix-dropdown-menu-content-transform-origin) overflow-y-auto rounded-md border bg-popover p-1 text-popover-foreground shadow-md data-[state=closed]:animate-out data-[state=closed]:fade-out-0 data-[state=closed]:zoom-out-95 data-[state=open]:animate-in data-[state=open]:fade-in-0 data-[state=open]:zoom-in-95"
        >
          {children}
        </DropdownMenuPrimitive.Content>
      </DropdownMenuPrimitive.Portal>
    </DropdownMenuPrimitive.Root>
  )
}

function FilterMenuItem({
  isSelected,
  className,
  children,
  ...props
}: React.ComponentProps<typeof DropdownMenuPrimitive.Item> & {
  isSelected?: boolean
}) {
  return (
    <DropdownMenuPrimitive.Item
      data-slot="filter-menu-item"
      className={cn(
        "relative flex cursor-default items-center gap-2 rounded-sm py-1.5 pr-8 pl-2 text-sm outline-hidden select-none focus:bg-accent focus:text-accent-foreground [&_svg]:pointer-events-none [&_svg]:shrink-0 [&_svg:not([class*='size-'])]:size-4 [&_svg:not([class*='text-'])]:text-muted-foreground",
        className
      )}
      {...props}
    >
      {children}
      {isSelected && <CheckIcon className="absolute right-2" />}
    </DropdownMenuPrimitive.Item>
  )
}

export { FilterMenu, FilterMenuItem }

import type { ReactNode } from "react"

export type FilterFieldType = "text" | "number" | "select"

export type FilterOperator =
  "contains" | "not-contains" | "is" | "is-not" | "eq" | "gt" | "lt"

export type FilterField = {
  id: string
  label: string
  type: FilterFieldType
  options?: { value: string; label: string }[]
  icon?: ReactNode
}

export type Filter = {
  id: string
  fieldId: string
  operator: FilterOperator
  value: string
}

const OPERATORS_BY_TYPE: Record<FilterFieldType, FilterOperator[]> = {
  text: ["contains", "not-contains", "is", "is-not"],
  number: ["eq", "gt", "lt"],
  select: ["is", "is-not"],
}

const OPERATOR_LABEL: Record<FilterOperator, string> = {
  contains: "contains",
  "not-contains": "does not contain",
  is: "is",
  "is-not": "is not",
  eq: "=",
  gt: ">",
  lt: "<",
}

export function operatorsFor(type: FilterFieldType) {
  return OPERATORS_BY_TYPE[type]
}

export function operatorLabel(operator: FilterOperator) {
  return OPERATOR_LABEL[operator]
}

export function createFilter(field: FilterField): Filter {
  return {
    id: Math.random().toString(36).slice(2),
    fieldId: field.id,
    operator: OPERATORS_BY_TYPE[field.type][0],
    value: "",
  }
}

export function matchesFilter(fieldValue: string | number, filter: Filter) {
  const text = String(fieldValue).toLowerCase()
  const needle = filter.value.toLowerCase()
  if (needle === "") return true

  switch (filter.operator) {
    case "contains":
      return text.includes(needle)
    case "not-contains":
      return !text.includes(needle)
    case "is":
      return text === needle
    case "is-not":
      return text !== needle
    case "eq":
      return Number(fieldValue) === Number(filter.value)
    case "gt":
      return Number(fieldValue) > Number(filter.value)
    case "lt":
      return Number(fieldValue) < Number(filter.value)
  }
}
